  insert into public.brands (name, website, description, country, status) values ('Hideaway', 'https://www.hideaway.online', 'Australian direct-to-consumer fragrance and bath/body brand (designer-inspired perfumes, body mists and body treats, made on the Gold Coast) running a Creator Commission Program through Shopify Collabs: 30% commission on organic sales, and its own program page explicitly markets unlimited earnings with no cap.', 'Australia', 'published') returning id into bid;
