  insert into public.affiliate_programs (brand_id, network, commission_rate, commission_notes, application_url, status, last_checked_at) values (bid, 'Shopify Collabs', 30, 'Commission cap: UNCAPPED — stated in the program terms (see evidence). Creator saturation: unknown (see evidence). Rate as reported by https://www.hideaway.online/pages/creators.', 'https://www.hideaway.online/pages/creators', 'needs_review', now());
  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Hideaway Creator Commission Program (Shopify Collabs)', 'https://www.hideaway.online/pages/creators', null, 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.hideaway.online/pages/creators', 'brand_site', 'affiliate_program', 'Hideaway''s own Creator Program page (fetched) states affiliates earn 30% commission on every sale through Shopify Collabs with a custom 10% follower discount code, under a page banner reading ''30% Commission - Unlimited Earnings'' and a stats block showing an infinity symbol for ''Earning Potential''. Its Paid Amplification tier states ''10% on every sale those ads generate, with zero cost to you and no cap on earnings'', ''Unlimited earning potential - no cap, ever'' and ''Tier 2 creators earn an additional 10% on all ad-driven sales - with no ceiling'', while the comparison table lists ''Capped earnings'' as a drawback of other programs. That is an explicit no-earnings-cap statement on the brand''s own program page, so commission_cap is recorded as uncapped and commission_rate as 30 (the Tier 1 organic rate).', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.hideaway.online/pages/creators', 'brand_site', 'brand_overview', 'The same page (fetched) describes designer-inspired perfumes and bath & body products made on the Gold Coast, Australia, says applications are reviewed within 3-5 business days, welcomes creators of all sizes (1,000 to 1,000,000 followers), and displays ''500+ Active Creators'' and ''$180k+ Creator Earnings Paid''. A creator count in the several-hundreds is not ~100-scale absolute evidence of a small cohort, so creator_saturation is recorded as unknown, not low.', 'verified', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 26, 18, 20, 8, 7, 4, '{"niche_fit": "Fragrance and bath/body are strong TikTok/Instagram content categories and the brand builds its marketing around creator haul and review posts.", "ugc_evidence": "The program page showcases named creator posts with like counts and states $180k+ in creator earnings paid.", "compensation": "30% is a top-tier beauty rate and the brand''s own page explicitly states unlimited earnings with no cap.", "contact_access": "Application form on the brand''s own page with a stated 3-5 business day review; no public email was published on the page fetched.", "opportunity_availability": "Open application for creators of all sizes, though the affiliate tier is labelled invite-only after review.", "credibility": "A smaller Australian DTC brand; it self-reports a 4.9-star average product rating on its own page."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Mario Badescu', 'https://www.mariobadescu.com', 'US skincare brand founded in 1967 with 200+ products, running a tiered creator affiliate program through Aspire: creators start at the Skin Squad tier earning 10% commission on every sale, with rates growing through tiers, a 15% audience discount code and product gifting.', 'United States', 'published') returning id into bid;
