  insert into public.affiliate_programs (brand_id, network, commission_rate, commission_notes, application_url, status, last_checked_at) values (bid, 'Brand direct (own program)', 10, 'Commission cap: not stated in any published source found — needs review. Creator saturation: unknown (see evidence). Rate as reported by https://mariobadescu.aspireiq.com/join/mario-badescu-affiliate-program?clientId=L5a4kB7nX508VLjlSu9Bv4k1ElxBy7I7.', 'https://mariobadescu.aspireiq.com/join/mario-badescu-affiliate-program?clientId=L5a4kB7nX508VLjlSu9Bv4k1ElxBy7I7', 'needs_review', now());
  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Mario Badescu Affiliate Program (Aspire)', 'https://mariobadescu.aspireiq.com/join/mario-badescu-affiliate-program?clientId=L5a4kB7nX508VLjlSu9Bv4k1ElxBy7I7', null, 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://mariobadescu.aspireiq.com/join/mario-badescu-affiliate-program?clientId=L5a4kB7nX508VLjlSu9Bv4k1ElxBy7I7', 'brand_site', 'affiliate_program', 'Mario Badescu''s own affiliate application page on Aspire (fetched) states creators begin at the entry ''Skin Squad'' tier earning a 10% commission on every sale they drive, with the rate growing as they move up program tiers, plus an exclusive 15% audience discount code, product gifting, monthly newsletters and training resources. ''The sky''s the limit'' on that page refers to tier progression and perks, not to an earnings-cap statement, so commission_cap is unknown. The page publishes the contact email felicia@mariobadescu.com for program questions.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://firstonlineprofits.com/new-fmtc-merchants-include-dollar-shave-club-spyder-brezza-myminipets-mario-badescu/', 'affiliate_directory', 'network_listing', 'An FMTC merchant roundup (fetched) lists Mario Badescu as an Awin advertiser (Awin #122442, Personal Care), confirming the brand also runs a conventional network affiliate program alongside its Aspire creator program. No creator count is published in any source fetched, so creator_saturation is unknown.', 'publicly_reported', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 28, 17, 12, 13, 8, 5, '{"niche_fit": "Iconic, affordable skincare with 200+ products is a staple of routine and empties content.", "ugc_evidence": "A dedicated tiered creator program with gifting, newsletters and training, plus a separate college ambassador scheme reported in search results.", "compensation": "10% starting rate that grows with tiers is solid for a mass skincare brand; cap not stated.", "contact_access": "A named program contact email is published directly on the application page, which is rare and valuable.", "opportunity_availability": "Open application for beauty and skincare creators; entry tier starts immediately on approval.", "credibility": "Heritage US brand operating since 1967 with wide retail distribution."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('TIRTIR', 'https://tirtir.global', 'Viral Korean beauty brand (Mask Fit Red Cushion, Milk Skin Toner) running TIRACLES, its own affiliate program for beauty influencers via Shopify Collabs with commissions starting at 5%, and one of the largest TikTok Shop affiliate operations in beauty, with tens of thousands of affiliates.', 'South Korea', 'published') returning id into bid;
