  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'TIRACLES by TIRTIR (Shopify Collabs) + TikTok Shop', 'https://tirtir.global/pages/affiliate-program', null, 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://tirtir.global/pages/affiliate-program', 'brand_site', 'affiliate_program', 'TIRTIR''s own affiliate page (fetched) describes TIRACLES, its exclusive affiliate program for beauty influencers: apply through the Shopify Collabs form, and once approved receive a one-time 35% personal discount code for content products, a creator discount code starting at 5% for the audience, and commissions starting at 5% with higher rates unlocked as you grow. No earnings-cap statement appears on the page, so commission_cap is unknown and commission_rate is recorded as the 5% starting rate.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.fastmoss.com/shop-marketing/detail/7495857443730262618', 'platform_data', 'creator_saturation', 'FastMoss data for the TIRTIR Inc. TikTok Shop store (fetched) shows 26,061 affiliates on the promotion channel and roughly 13,400 affiliates in store analytics, with active products commonly paying 10% commission. Tens of thousands of affiliates is absolute-terms evidence of a heavily saturated creator program, so creator_saturation is recorded as high.', 'publicly_reported', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 29, 20, 8, 7, 6, 5, '{"niche_fit": "The Mask Fit cushion is one of the most-covered K-beauty products on TikTok; the brand recruits Instagram, TikTok and YouTube beauty creators directly.", "ugc_evidence": "A named influencer program plus a TikTok Shop affiliate army of roughly 26,000 creators is maximal creator-program evidence.", "compensation": "5% starting commission is low for beauty and only rises with performance; TikTok Shop rates around 10% are better but still mid-pack.", "contact_access": "Application runs through the brand''s own page and Shopify Collabs; no public program email was found.", "opportunity_availability": "Applications are open, but with tens of thousands of affiliates the realistic opportunity per creator is diluted.", "credibility": "Major K-beauty brand with 1.1M+ TikTok Shop sales and global retail presence."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('PURITO Seoul', 'https://www.purito.com', 'Korean sensitive-skin brand (Centella, oat and panthenol lines) running the PURITO Seoul Privileges creator program: selected creators get a dedicated Amazon Attribution link through the Coral platform paying 15% of net sales, alongside recurring TikTok Shop affiliate challenges for hero products.', 'South Korea', 'published') returning id into bid;
