  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'PURITO Seoul Privileges (Coral / Amazon Attribution) + TikTok Shop', 'https://coral.ax/a/1onzo', null, 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://coral.ax/a/1onzo', 'program_page', 'affiliate_program', 'The PURITO Seoul Privileges Amazon Sales Bonus sign-up page on the Coral affiliate platform (fetched) states selected creators receive a unique Amazon Attribution link and earn 15% of net sales generated through it, with commissions calculated monthly and creator payouts processed around the 15th of the month; only sales tracked through the official link qualify. No earnings-cap statement appears, so commission_cap is unknown, and the program is limited to selected creators invited from the Privileges campaign.', 'publicly_reported', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.notion.so/PURITO-SEOUL-PeelForTheGold-Affiliate-Challenge-2f72ce2a77da807bac39eb97d8dd7a15', 'program_page', 'affiliate_program', 'A PURITO Seoul affiliate challenge page (fetched) shows the brand also recruits TikTok Shop affiliates for product campaigns (post at least 5 TikTok shoppable videos of the Peel Shot Exfoliating Pad, minimum cumulative GMV target), confirming an active TikTok Shop affiliate route in addition to the Privileges/Coral program. No creator count is published in either source, so creator_saturation is unknown.', 'publicly_reported', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 28, 16, 14, 6, 5, 4, '{"niche_fit": "Barrier-care and sensitive-skin K-beauty is a central skincare content niche and the brand recruits skincare creators specifically.", "ugc_evidence": "A named creator program (Privileges) with structured TikTok Shop affiliate challenges and content guidelines.", "compensation": "15% of net sales is above the K-beauty norm; cap not stated.", "contact_access": "Access runs through campaign selection and the Coral platform; no public partnership email was found on the pages fetched.", "opportunity_availability": "The 15% program is limited to selected creators rather than open application; TikTok Shop challenges are the more open route.", "credibility": "Well-established Korean skincare brand with strong Amazon and TikTok Shop presence."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Soko Glam', 'https://sokoglam.com', 'Leading US K-beauty retailer and curator whose Soko Ambassador affiliate program lets creators, publishers and skincare enthusiasts earn commission across its curated Korean skincare catalogue, via Pepperjam, Skimlinks, LTK, ShopMy and Shopify Collabs.', 'United States', 'published') returning id into bid;
