  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Soko Ambassador Affiliate Program (Pepperjam and others)', 'https://sokoglam.com/pages/affiliate-program', null, 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://sokoglam.com/pages/affiliate-program', 'brand_site', 'affiliate_program', 'Soko Glam''s own affiliate page (fetched) invites creators to become a Soko Ambassador and earn commission on sales, with early access to launches, exclusive promos and dedicated affiliate support, and states the program is available on Pepperjam, Skimlinks, LTK, ShopMy and Shopify Collabs. The brand''s own page does not publish a rate or any earnings-cap statement, so commission_cap is unknown.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.flexoffers.com/affiliate-programs/soko-glam-affiliate-program/', 'affiliate_directory', 'network_listing', 'FlexOffers'' Soko Glam program listing (fetched) reports a 4% commission on sales, while Shopper.com''s partnership listing reports a 1% payout and other roundups claim up to 10%. Published rates conflict (1% / 4% / up to 10%), so commission_rate is recorded as null and must be confirmed inside the chosen network. No creator count is published in any source fetched, so creator_saturation is unknown.', 'publicly_reported', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 27, 15, 6, 7, 8, 5, '{"niche_fit": "A curated K-beauty catalogue gives skincare creators many products to build routines and haul content around.", "ugc_evidence": "A named ambassador program with dedicated affiliate support and media assets across five creator platforms.", "compensation": "Rates conflict across every published source (1% / 4% / up to 10%) and even the highest figure is modest for a retailer program.", "contact_access": "Program page on the brand''s own site with multiple join routes; no public program email found.", "opportunity_availability": "Open to enthusiasts, creators and publishers through five different platforms, so access is easy.", "credibility": "One of the best-known US K-beauty retailers, founded by a published skincare author, with a long operating history."}'::jsonb);
