  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 27, 14, 11, 5, 7, 4, '{"niche_fit": "Double cleansing and fermented-essence routines are established K-beauty content formats and the brand is creator-recognised.", "ugc_evidence": "Active TikTok Shop affiliate listings with per-sale commission displayed; the brand was also named among Shopify Collabs brands in a fetched industry roundup.", "compensation": "10% on TikTok Shop is standard for premium skincare; cap not stated.", "contact_access": "No public partnership contact was found on the pages fetched; access runs through TikTok Shop.", "opportunity_availability": "TikTok Shop affiliate access is open to eligible creators, though only a small product range (9 items) is listed.", "credibility": "Founder-led premium brand from the Soko Glam founder with strong editorial coverage."}'::jsonb);
