  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 26, 12, 11, 5, 7, 4, '{"niche_fit": "Ingredient-education skincare (retinol, vitamin C, hydration) maps directly onto high-performing skincare explainer content.", "ugc_evidence": "A long-running network affiliate program, though no dedicated creator or ambassador scheme was found.", "compensation": "10% with an unusually long 90-day cookie is competitive for drugstore-priced skincare; cap not stated.", "contact_access": "No public partnership email found; access runs through the ShareASale application.", "opportunity_availability": "Standard open network application with no stated follower minimum.", "credibility": "Established Canadian skincare brand with international retail distribution; program listing is somewhat dated."}'::jsonb);
