  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Kiyoko Beauty Affiliate Program (Refunnel)', 'https://kiyoko.com/pages/kiyoko-affiliate-program', null, 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://kiyoko.com/pages/kiyoko-affiliate-program', 'brand_site', 'affiliate_program', 'Kiyoko Beauty''s own affiliate page (fetched) states affiliates earn 10% commission on every first-time customer purchase and 5% for repeat customers through their link or code, with tiered levels (Superstar on joining, Insider at 5+ lifetime sales, Affiliate at 10+), one-time cash milestone rewards ($5 at 1 sale up to $70 at 50 sales), monthly gifting campaigns and a WhatsApp affiliate community; sign-up runs through its Refunnel dashboard. No earnings-cap statement appears on the page, so commission_cap is unknown.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://kiyoko.com/pages/kiyoko-affiliate-program', 'brand_site', 'brand_overview', 'The same page (fetched) positions Kiyoko as a retailer built to support creators sharing Asian beauty, contrasting its 10% first-order rate with the 5-8% it says many retailers offer. No creator count is published anywhere on the page, so creator_saturation is unknown.', 'verified', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 26, 16, 11, 7, 8, 3, '{"niche_fit": "A curated K-beauty/J-beauty catalogue gives skincare creators a wide product range for routine and haul content.", "ugc_evidence": "A creator-first program with monthly gifting campaigns, tier names, milestone rewards and an affiliate WhatsApp community.", "compensation": "10% on first orders is fair for a retailer and milestone cash bonuses add upside; 5% on repeats and no cap statement keep it mid-pack.", "contact_access": "Program page and dashboard sign-up on the retailer''s own site; no public email found.", "opportunity_availability": "Open application with the entry tier granted on joining and no stated follower minimum.", "credibility": "A small, young US Asian-beauty retailer with limited public footprint compared with national chains."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Fresh', 'https://www.fresh.com', 'LVMH-owned skincare brand (Soy Face Cleanser, Rose and Black Tea lines) whose own affiliate page invites publishers to earn commission through Rakuten Advertising at a 5% base rate, with affiliate-only promotions and launch previews.', 'United States', 'published') returning id into bid;
