  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.fresh.com/us/affiliatepage.html', 'brand_site', 'affiliate_program', 'Fresh''s own affiliates page (fetched) states: ''Fresh publishers earn revenue by promoting fresh products and promotions that they love on their site. We work with Rakuten to make it even easier'' and ''Receive a 5% base with opportunities to individually optimize your earnings'', plus affiliate-only promotions, exclusive newsletters and product launch sneak peeks, with applications reviewed before approval. No earnings-cap statement appears on the page, so commission_cap is unknown, and no creator count is published, so creator_saturation is unknown.', 'verified', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 27, 12, 8, 6, 7, 5, '{"niche_fit": "Heritage skincare franchises (Soy, Rose, Black Tea) are reliable review and routine content subjects.", "ugc_evidence": "A documented publisher affiliate program with affiliate-only promotions and launch previews, though it is publisher- rather than creator-led.", "compensation": "5% base is low for beauty, partly offset by the stated possibility of individually optimised rates; cap not stated.", "contact_access": "Program page on the brand''s own site routes to the Rakuten application; no public program email found.", "opportunity_availability": "Open publisher application on a major network, subject to site review and approval.", "credibility": "An LVMH house brand with global retail presence and decades of operating history."}'::jsonb);
