  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 25, 13, 16, 6, 7, 4, '["Swim and resort wear is a top-performing fashion/travel creator category, and Summersalt is a category-defining brand.", "The brand is heavily promoted by swim and lifestyle creators, though tracked program data is thin.", "A reported 15% commission is at the top of the fashion range; no cap statement was found, so the cap is unknown.", "No public partnerships contact was found; access is via the network listing only.", "Application through the Offerspilot network per the program review.", "Well-known DTC brand, but the program terms rest on a single review source."]'::jsonb);
