  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 25, 13, 13, 10, 8, 5, '["K\u00e5nken backpacks and outdoor apparel sit squarely in the travel and outdoor creator niche.", "A long-running program with seasonal campaigns; tracked creator data is not published.", "A brand-published 10% base commission with stated room to increase; no cap statement, so the cap is unknown.", "The brand''s own program page promises a dedicated in-house affiliate manager and customer success team.", "Open sign-up through AvantLink from the brand''s own page.", "Heritage Swedish outdoor brand with global retail presence."]'::jsonb);
