  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://linkclicky.com/affiliate-program/birdies/', 'affiliate_directory', 'affiliate_program', 'LinkClicky''s BIRDIES listing (fetched) reports the program on the ShareASale platform paying 15% per sale with a 30-day cookie, open to all regions. Sovrn Commerce also lists a BIRDIES affiliate program but does not publish its rate. The 15% figure rests on one directory source, so it is marked publicly_reported. No fetched source states an earnings cap, so commission_cap is unknown.', 'publicly_reported', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 24, 12, 16, 7, 8, 4, '["Comfort-driven designer flats are a proven women''s fashion creator niche.", "A live ShareASale program; published creator campaign data is limited.", "A reported 15% commission is top-tier for footwear; no cap statement found, so the cap is unknown.", "Application via the ShareASale listing; no public brand partnerships email found.", "Open application through ShareASale.", "Well-known DTC footwear brand; rate rests on a single directory source."]'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('GoMacro', 'https://www.gomacro.com', 'Plant-based, organic nutrition bar brand (MacroBars) founded in Wisconsin. It runs its own Brand Ambassador Program: ambassadors get a custom code giving their audience 25% off gomacro.com, earn 10% commission on every purchase made with the code, receive a free tray of bars monthly, and are paid monthly through the Impact platform. Ambassadors must post at least once a month tagging @GoMacro.', 'United States', 'published') returning id into bid;
  insert into public.brand_categories (brand_id, category_id, is_primary) values (bid, (select id from public.categories where slug = 'food-drink'), true);
  insert into public.brand_contacts (brand_id, contact_type, email, contact_url, source_url, verification_status, last_verified_at) values (bid, 'creator_application', 'ambassadors@gomacro.com', 'https://gomacro.com/pages/brand-ambassador', 'https://gomacro.com/pages/brand-ambassador', 'verified', now());
  insert into public.brand_contacts (brand_id, contact_type, email, contact_url, source_url, verification_status, last_verified_at) values (bid, 'partnerships', 'mia@gomacro.com', 'https://gomacro.com/pages/brand-ambassador-requirements', 'https://gomacro.com/pages/brand-ambassador-requirements', 'verified', now());
  insert into public.affiliate_programs (brand_id, network, commission_rate, commission_notes, application_url, status, last_checked_at) values (bid, 'Impact', 10, 'Commission cap: not stated in any published source found — needs review. Creator saturation: unknown (see evidence). Rate as reported by https://gomacro.com/pages/brand-ambassador-requirements.', 'https://gomacro.com/pages/brand-ambassador', 'needs_review', now());
  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'GoMacro Brand Ambassador Program — 10% commission via custom code, paid monthly through Impact, free product monthly', 'https://gomacro.com/pages/brand-ambassador', 'https://gomacro.com/pages/brand-ambassador-requirements', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://gomacro.com/pages/brand-ambassador-requirements', 'official_site', 'affiliate', 'GoMacro''s official Brand Ambassador Requirements page, fetched in full: ambassadors earn 10% commission on purchases made with their custom code (25% off for the audience), receive one free tray of MacroBars monthly, and ''Payments are made through the Impact platform and are distributed monthly.'' Ambassadors are expected to post at least once per month tagging @GoMacro with #gomacropartner. The page publishes the contact mia@gomacro.com for event/partnership outreach. No earnings-cap statement and no creator count are published, so cap and saturation stay unknown.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://gomacro.com/pages/brand-ambassador', 'official_site', 'affiliate', 'GoMacro''s official Brand Ambassador page describes the program''s pillars (earn commission, collect rewards, community, sneak peeks), a challenge/rewards structure run through a management platform, 6-monthly ambassador reviews, and the application contact ambassadors@gomacro.com.', 'verified', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 27, 18, 12, 14, 9, 5, '{"niche_fit": "Organic plant-based bars are core food/wellness creator content, and the brand brief explicitly spans Instagram, TikTok, YouTube and Facebook.", "ugc_evidence": "A structured ambassador program with monthly posting requirements, branded hashtags, challenges and rewards \u2014 built for recurring UGC.", "compensation": "10% commission is mid-band for food; the 25%-off audience code and free monthly product add value, but no cap statement is published.", "contact_access": "Two published brand emails (ambassadors@ and a named partnerships contact) plus an open application page.", "opportunity_availability": "Applications are open on the brand''s own site now; ambassadors are reviewed every six months rather than the program being closed.", "credibility": "Long-established national bar brand sold across US grocery; program terms are published on its own domain."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Lemme', 'https://lemme.com', 'Botanical gummy vitamin and supplement brand co-founded by Kourtney Kardashian Barker (Lemme Debloat, Purr, Glow). Its Ambassador and Affiliate Program runs primarily through the Impact network and TikTok Shop; reported commission is 10%-20% per sale. Lemme''s TikTok Shop affiliate engine is one of the largest in wellness — reported at more than 13,000 commission-paid creators producing 53,000+ videos in a single quarter — so saturation is high even though entry is open.', 'United States', 'published') returning id into bid;
  insert into public.brand_categories (brand_id, category_id, is_primary) values (bid, (select id from public.categories where slug = 'wellness'), true);
  insert into public.affiliate_programs (brand_id, network, commission_rate, commission_notes, application_url, status, last_checked_at) values (bid, 'TikTok Shop', 10, 'Commission cap: not stated in any published source found — needs review. Creator saturation: high (see evidence). Rate as reported by https://www.affililist.com/affiliate/lemme.', 'https://www.affililist.com/affiliate/lemme', 'needs_review', now());
  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Lemme Ambassador & Affiliate Program — 10%-20% reported via Impact and TikTok Shop; 13,000+ creators already in (high saturation)', 'https://www.affililist.com/affiliate/lemme', 'https://femfounded.org/case-studies/lemme/', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.affililist.com/affiliate/lemme', 'directory', 'affiliate', 'AffiliList''s Lemme program profile, fetched in full: the Lemme Ambassador and Affiliate Program ''primarily operates through the Impact network and TikTok Shop'', with a dedicated tracking dashboard, ambassador gifting and early product access; the directory''s program listing reports commission of 10%-20% per sale, paid monthly via PayPal or ACH. The recorded rate is the 10% floor of that reported range. No earnings-cap statement is published, so cap stays unknown.', 'publicly_reported', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://femfounded.org/case-studies/lemme/', 'directory', 'creator_program', 'Femfounded''s Lemme case study reports the brand''s TikTok Shop affiliate engine at more than 13,000 creators and 53,000+ videos in a single quarter, driving $13M through TikTok Shop in November 2025, with commission-only affiliate links as the core model. That absolute creator count (13,000+) is the basis for the ''high'' creator saturation rating.', 'publicly_reported', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 28, 20, 14, 8, 8, 5, '{"niche_fit": "Gummy vitamins for debloat, sleep, focus and beauty are peak wellness-creator content with proven TikTok demand.", "ugc_evidence": "53,000+ affiliate videos in a quarter is the strongest UGC evidence in this group \u2014 the whole growth model is creator content.", "compensation": "Reported 10%-20% per sale is top-band for supplements; the recorded 10 is the published floor of the range, and no cap statement is published.", "contact_access": "No public creator email was found on the fetched pages; entry is via Impact/TikTok Shop dashboards only.", "opportunity_availability": "Open enrollment through TikTok Shop and Impact, but a new creator competes with 13,000+ existing affiliates.", "credibility": "Celebrity-founded brand with national retail (Target, Walmart, Erewhon) and verified nine-figure-scale sales reporting."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Vital Proteins', 'https://www.vitalproteins.com', 'The leading US collagen brand (Collagen Peptides, marine collagen, beauty collagen), owned by Nestlé Health Science. It runs an affiliate/influencer program through Impact plus a self-hosted influencer route. Published commission figures conflict across sources (4%, 6%/13% UK tiers, 10%, 15% self-hosted, and a 25% Impact Amazon-seller listing), so the rate is recorded as null with the conflict documented rather than guessed.', 'United States', 'published') returning id into bid;
  insert into public.brand_categories (brand_id, category_id, is_primary) values (bid, (select id from public.categories where slug = 'wellness'), true);
  insert into public.affiliate_programs (brand_id, network, commission_rate, commission_notes, application_url, status, last_checked_at) values (bid, 'Impact', null, 'Commission cap: not stated in any published source found — needs review. Creator saturation: unknown (see evidence). Rate as reported by https://www.netinfluencer.com/vital-proteins-influencer-program/.', 'https://www.vitalproteins.com/', 'needs_review', now());
  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Vital Proteins Affiliate & Influencer Program via Impact — rate unpublished consistently (4%-25% reported by route); confirm in-network before promoting', 'https://www.vitalproteins.com/', 'https://www.creator-hero.com/blog/top-20-best-us-health-wellness-influencer-affiliate-programs', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.creator-hero.com/blog/top-20-best-us-health-wellness-influencer-affiliate-programs', 'directory', 'affiliate', 'Creator Hero''s program roundup lists Vital Proteins at 10% per sale with a 30-day cookie, free shipping perks and influencer campaigns, with sign-up via vitalproteins.com. This conflicts with other published figures (below), so no single rate is recorded.', 'publicly_reported', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.netinfluencer.com/vital-proteins-influencer-program/', 'directory', 'affiliate', 'NetInfluencer''s Vital Proteins profile states the brand runs both an affiliate program and an influencer/ambassador program, describing a self-hosted program paying 15% commission with a 7-day cookie. Other fetched sources report 6% and 13% tiers for the UK Impact program, 4% for the CA program and a 25% Impact listing for its Amazon Seller storefront. Because the published rates conflict (4%-25% depending on route/region), commission_rate is null; no earnings-cap statement or creator count is published in any fetched source, so cap and saturation stay unknown.', 'publicly_reported', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 26, 16, 8, 8, 8, 5, '{"niche_fit": "Collagen is a staple of beauty-from-within, fitness and wellness content; the product line maps to many creator niches.", "ugc_evidence": "Both an affiliate program and a separate influencer/ambassador program with campaign access are documented.", "compensation": "Held down: published rates conflict across routes and regions (4%-25%), so no rate is recorded until confirmed inside Impact.", "contact_access": "Application runs through the brand site and Impact; no public creator email was published on the fetched pages.", "opportunity_availability": "Program is live and recruiting across several network storefronts (US, UK, CA, Amazon Seller).", "credibility": "Category-defining brand owned by Nestl\u00e9 Health Science, with the #1 collagen powder position in the US."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('WelleCo', 'https://www.welleco.com', 'Premium plant-based wellness brand founded by Elle Macpherson (The Super Elixir greens, Nourishing Protein, ingestible beauty). Its affiliate program runs through the Impact network. Published rates conflict — one directory reports 5% per sale while another reports 10% per sale on Impact — so the rate is recorded as null with the conflict documented. WelleCo also maintains an official affiliate program page on its Australian store.', 'Australia', 'published') returning id into bid;
  insert into public.brand_categories (brand_id, category_id, is_primary) values (bid, (select id from public.categories where slug = 'wellness'), true);
  insert into public.affiliate_programs (brand_id, network, commission_rate, commission_notes, application_url, status, last_checked_at) values (bid, 'Impact', null, 'Commission cap: not stated in any published source found — needs review. Creator saturation: unknown (see evidence). Rate as reported by https://linkclicky.com/affiliate-program/welleco/.', 'https://welleco.com.au/pages/affiliate-program', 'needs_review', now());
  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'WelleCo Affiliate Program via Impact — premium greens/protein brand; published rate conflicts (5% vs 10%), confirm in-network', 'https://welleco.com.au/pages/affiliate-program', 'https://linkclicky.com/affiliate-program/welleco/', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://linkclicky.com/affiliate-program/welleco/', 'directory', 'affiliate', 'LinkClicky''s WelleCo profile lists the affiliate platform as Impact with a commission of 10% per sale. A second directory (GetLasso) reports 5% per sale for the same program. The two published figures conflict, so commission_rate is recorded as null rather than picking one. No earnings-cap statement and no creator count are published in either source, so cap and saturation stay unknown.', 'publicly_reported', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://welleco.com.au/pages/affiliate-program', 'official_site', 'affiliate', 'WelleCo''s official Australian store carries a dedicated Affiliate Program page (fetched; the page body is a sign-up promotion for the program), confirming the brand operates its own affiliate program page alongside the Impact listing.', 'verified', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 24, 12, 8, 7, 7, 4, '{"niche_fit": "Premium greens and ingestible beauty fit wellness and beauty-from-within creators well, at a higher price point than most.", "ugc_evidence": "An official affiliate page plus an Impact listing show a standing program, but creator-specific content evidence is thinner than peers.", "compensation": "Held down: the two published rates conflict (5% vs 10%), so no rate is recorded until confirmed inside Impact.", "contact_access": "Routes are the official affiliate page and Impact application; no public creator email found on fetched pages.", "opportunity_availability": "Program is listed as open on Impact and promoted on the brand''s own AU store.", "credibility": "Established premium brand founded by Elle Macpherson with international retail presence; a point held back for the rate conflict."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Supersmart', 'https://us.supersmart.com', 'Long-running supplement brand (founded 1992) selling a wide catalogue of vitamins, antioxidants and specialty formulas through its US storefront. Its affiliate program runs on CJ Affiliate (tiered 10% base, rising to 11%/12%/13% at $1,000/$2,000/$5,000 in sales) and Webgains (fixed 11%) — all stated on the brand''s own official FAQ page. Free to join with no minimum sales requirement.', 'France', 'published') returning id into bid;
  insert into public.brand_categories (brand_id, category_id, is_primary) values (bid, (select id from public.categories where slug = 'health'), true);
  insert into public.affiliate_programs (brand_id, network, commission_rate, commission_notes, application_url, status, last_checked_at) values (bid, 'CJ', 10, 'Commission cap: not stated in any published source found — needs review. Creator saturation: unknown (see evidence). Rate as reported by https://us.supersmart.com/en/faq/affiliate-program.', 'https://us.supersmart.com/en/faq/affiliate-program', 'needs_review', now());
  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Supersmart Affiliate Program on CJ — 10% base commission tiering to 13%, free to join, terms on the brand''s own FAQ', 'https://us.supersmart.com/en/faq/affiliate-program', 'https://us.supersmart.com/en/faq/affiliate-program', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://us.supersmart.com/en/faq/affiliate-program', 'official_site', 'affiliate', 'Supersmart''s official affiliate FAQ, fetched in full: ''Supersmart''s CJ Affiliate Program provides commissions that begin at 10%'' with performance tiers of 11% at $1,000+ sales, 12% at $2,000+ and 13% at $5,000+; the Webgains program pays a fixed 11%. Registration is free, there is no minimum sales amount, and affiliates apply by searching ''SuperSmart'' inside CJ Affiliate or Webgains. The FAQ answers the commission-rate question but publishes no earnings-cap statement and no creator count, so cap and saturation stay unknown. The recorded route is CJ Affiliate at the 10% base rate.', 'verified', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 22, 10, 13, 9, 9, 4, '{"niche_fit": "A broad supplement catalogue gives health creators many angles, though the brand is less social-first than DTC peers.", "ugc_evidence": "Classic link/banner affiliate structure rather than a creator-content program; UGC evidence is the weakest in this group.", "compensation": "10% base verified on the brand''s own FAQ, tiering to 13% on CJ and a fixed 11% alternative on Webgains; no cap statement published.", "contact_access": "Clear application route inside CJ/Webgains plus a contact link on the official FAQ page.", "opportunity_availability": "Free to join with no minimum sales requirement, per the brand''s own FAQ \u2014 open now.", "credibility": "Operating since 1992 with terms published on its own domain; a point held back for limited creator-program presence."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Three Spirit', 'https://threespiritdrinks.com', 'B Corp functional non-alcoholic spirits brand (Livener, Social Elixir, Nightcap) built on botanical alchemy. Three Spirit lists affiliate marketing among the partnership opportunities on its official US Community/Collabs page and runs network affiliate programs on Awin (merchant #19933) and Impact. Published rate ranges conflict between networks (1.6%-6.4% on the Awin-side listing vs 2%-8% on Impact), so the rate is recorded as null with the conflict documented.', 'United Kingdom', 'published') returning id into bid;
  insert into public.brand_categories (brand_id, category_id, is_primary) values (bid, (select id from public.categories where slug = 'food-drink'), true);
  insert into public.affiliate_programs (brand_id, network, commission_rate, commission_notes, application_url, status, last_checked_at) values (bid, 'Awin', null, 'Commission cap: not stated in any published source found — needs review. Creator saturation: unknown (see evidence). Rate as reported by https://us.threespiritdrinks.com/pages/collab.', 'https://us.threespiritdrinks.com/pages/collab', 'needs_review', now());
  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Three Spirit Affiliate & Collabs — non-alcoholic functional spirits on Awin/Impact plus an official collabs route; rates conflict by network', 'https://us.threespiritdrinks.com/pages/collab', 'https://linkclicky.com/affiliate-program/three-spirit/', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://us.threespiritdrinks.com/pages/collab', 'official_site', 'affiliate', 'Three Spirit''s official US Community page, fetched in full: under ''Partnership opportunities'' the brand lists affiliate marketing, gifting, discount codes and content creation, inviting creators to ''become a Three Spirit alchemist''. (Its separate US referral program pays store-credit coupons and is not the recorded route.)', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://linkclicky.com/affiliate-program/three-spirit/', 'directory', 'affiliate', 'LinkClicky lists Three Spirit''s affiliate platform as Impact at 2%-8% per sale, while an Awin-side program listing (FMTC merchant record: Three Spirit Drinks, Awin #19933) is reported at 1.6%-6.4% with a 30-day cookie. Because the published ranges conflict by network, commission_rate is null; no earnings-cap statement or creator count is published in any fetched source, so cap and saturation stay unknown.', 'publicly_reported', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 24, 14, 7, 8, 7, 4, '{"niche_fit": "Non-alcoholic functional drinks are a fast-growing sober-curious niche with strong cocktail-content potential.", "ugc_evidence": "The official collabs page names affiliate marketing and content creation as standing partnership routes, plus a brand ambassador program.", "compensation": "Held down: published ranges are low and conflict by network (1.6%-6.4% vs 2%-8%), so no rate is recorded.", "contact_access": "Official US collab application page is the way in; no public creator email on the fetched pages.", "opportunity_availability": "Collabs and network programs are live, though the brand states it works with a limited number of sites on the network side.", "credibility": "Certified B Corp with US and UK stores and established retail distribution."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Koa Coffee', 'https://koacoffee.com', 'Hawaiian coffee grower selling 100% Kona coffee direct from its Kona Belt plantation (Forbes-dubbed ''Best Coffee in America''; Gevalia Kona Coffee Cupping Competition winner). Its official Awin merchant profile states affiliates are paid 10%-20% commission with a 45-day cookie. The recorded rate is the 10% floor of the profile''s published range.', 'United States', 'published') returning id into bid;
  insert into public.brand_categories (brand_id, category_id, is_primary) values (bid, (select id from public.categories where slug = 'food-drink'), true);
  insert into public.affiliate_programs (brand_id, network, commission_rate, commission_notes, application_url, status, last_checked_at) values (bid, 'Awin', 10, 'Commission cap: not stated in any published source found — needs review. Creator saturation: unknown (see evidence). Rate as reported by https://ui.awin.com/merchant-profile/88019.', 'https://ui.awin.com/merchant-profile/88019', 'needs_review', now());
  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Koa Coffee Affiliate Program on Awin — 10%-20% commission and a 45-day cookie, stated on the official merchant profile', 'https://ui.awin.com/merchant-profile/88019', 'https://ui.awin.com/merchant-profile/88019', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://ui.awin.com/merchant-profile/88019', 'official_site', 'affiliate', 'Koa Coffee''s official Awin merchant profile, fetched in full: ''We pay affiliates 10%-20% commission, with a 45 day cookie.'' The profile confirms the coffee is 100% Kona, grown, processed, roasted and shipped from the brand''s own Hawaiian plantation. It publishes no earnings-cap statement and no creator count, so cap and saturation stay unknown. The recorded rate is the 10% floor of the published range.', 'verified', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 22, 10, 14, 8, 8, 4, '{"niche_fit": "Premium single-origin Kona coffee suits coffee, food and morning-routine creators; a narrower niche than snacks or supplements.", "ugc_evidence": "A classic network affiliate program rather than a creator-content scheme; UGC evidence is limited to the Awin listing.", "compensation": "10%-20% published on the official Awin profile with a generous 45-day cookie; recorded at the 10% floor, no cap statement published.", "contact_access": "Application is through the Awin merchant profile; no public creator email on the fetched page.", "opportunity_availability": "Program is live on Awin and open to publisher applications.", "credibility": "Estate grower with named competition wins and national press recognition, per its own Awin profile."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Fly By Jing', 'https://flybyjing.com', 'Premium Chinese chili crisp and pantry brand founded by chef Jing Gao (Sichuan Chili Crisp). Food creators sell Fly By Jing through TikTok Shop affiliate codes and links — its listed creator route is the TikTok Shop affiliate program. No commission rate is published in the checked sources, so the rate is null. The brand''s published PR contact is flybyjing@isetta.co (press inquiries).', 'United States', 'published') returning id into bid;
