  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Fly By Jing TikTok Shop Affiliate — chili crisp creators earn via TikTok Shop codes/links; rate set inside TikTok Shop', 'https://www.bravodm.com/brands/flybyjing', 'https://www.bravodm.com/brands/flybyjing', 'unverified', 'ugc');
