  insert into public.brands (name, website, description, country, status) values ('Partake Foods', 'https://partakefoods.com', 'Black-owned, women-led allergy-friendly food brand (cookies, baking mixes, breakfast products free from the top 9 allergens), founded by Denise Woodard and sold nationally at Target, Walmart and Kroger. Partake runs an affiliate program through an affiliate network at roughly 5% commission, open to creator applicants (program facts checked by BravoDM, October 2026).', 'United States', 'published') returning id into bid;
