  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 24, 12, 9, 7, 8, 4, '{"niche_fit": "Allergy-friendly cookies and mixes serve a loyal parent and allergy-community creator niche underserved by mainstream snack brands.", "ugc_evidence": "A standing affiliate program open to creator applicants is documented, though content-program detail is thinner than peers.", "compensation": "Roughly 5% is low-band for food; two independent directories agree on the figure, and no cap statement is published.", "contact_access": "Application runs through the network listing; no public creator email was published on the fetched pages.", "opportunity_availability": "Program is listed as open to creator applicants now.", "credibility": "National retail distribution and a well-documented founder story; a point held back for the low rate and thin program detail."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Vive Organic', 'https://viveorganic.com', 'Wellness-shot brand (immunity, energy and glow shots with turmeric, ginger and adaptogens). Vive Organic runs its own Adventure Ambassadors program from its official site — its ambassadors page showcases named creator ambassadors (including professional surfer Brianna Cope and adventurer Mirna Valerio) with an open ''Become a Vive Ambassador'' join route. No commission rate is published on the fetched official pages, so the rate is null.', 'United States', 'published') returning id into bid;
