  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 24, 14, 6, 8, 7, 4, '{"niche_fit": "Wellness shots fit health, outdoor and adventure creator content \u2014 the brand''s ambassador roster is built around exactly those niches.", "ugc_evidence": "Named, spotlighted ambassadors on the official page prove an active creator program, though content requirements aren''t published.", "compensation": "Lowest in this group: no commission rate is published anywhere fetched, so the rate is null and terms only surface on application.", "contact_access": "Open ''Join Now'' route on the official ambassadors page; no public program email published.", "opportunity_availability": "The ambassador program is live and recruiting from the brand''s own site.", "credibility": "Established wellness-shot brand with national grocery distribution; a point held back for unpublished terms."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Zendure', 'https://www.zendure.com', 'Portable power stations, solar generators and home energy storage (SuperBase and SolarFlow lines) from an EnergyTech brand founded in Silicon Valley. Its own affiliate page routes creators, influencers, publishers and bloggers into its Impact program with a published per-sale commission and a 30-day cookie.', 'United States', 'published') returning id into bid;
