  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Zendure Affiliate Program on Impact — 5% per sale (tiers to 10%), 30-day cookie', 'https://zendure.com/pages/affiliate-program', 'https://zendure.com/pages/affiliate-program', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://zendure.com/pages/affiliate-program', 'official_site', 'affiliate', 'Zendure''s own affiliate program page fetched in full: ''Join us and enjoy upto 10% commission now'', a commission panel stating ''Up to 5% commission on each sale'', ''Use 30-day cookies duration'', an extra audience discount, and a free three-step sign-up. The page''s join link points to Zendure''s Impact campaign (''Zendure-SuperCharged-EnergyTech-Start-ups'' on app.impact.com), and the copy expressly invites social media influencers, content creators, publishers and bloggers. Recorded rate is the published 5% per-sale figure, with headline performance tiers up to 10%. No earnings-cap statement and no creator count are published, so cap and saturation stay unknown.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://ui.awin.com/merchant-profile/68786', 'network', 'affiliate', 'Zendure''s EU program on Awin (''Zendure EU Marketing'') lists 5% commission per sale and a 30-day cookie window for its SolarFlow home-storage line, corroborating the 5% base rate on the brand''s own US page. No cap statement or creator count is published.', 'publicly_reported', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 24, 14, 10, 8, 8, 4, '{"niche_fit": "Portable power and home-backup gear is proven tech/home creator content \u2014 reviews, outage prep and off-grid builds.", "ugc_evidence": "The brand''s own program page expressly recruits influencers, content creators, publishers and bloggers, with an audience discount to share.", "compensation": "Published 5% per sale with headline tiers up to 10% and a 30-day cookie; high order values help, but the base rate is mid-band and no cap statement is published.", "contact_access": "One route in: the Impact application linked from the brand''s page. No published affiliate email.", "opportunity_availability": "Program is live and free to join per the brand''s page; approval sits with the network listing.", "credibility": "Established energy-tech brand with consistent 5% reporting across its own page and its Awin EU listing."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('ALLPOWERS', 'https://iallpowers.com', 'Portable power stations, solar panels and solar generator kits for camping, RV, emergency preparedness and home backup. Its own affiliate page is built around creators and influencers, publishes a 5% base rate with performance tiers to 10%, a 30-day cookie, a $500+ average order value and a named affiliate-team email, with joining via CJ, Awin, AvantLink or GoAffPro.', 'China', 'published') returning id into bid;
