  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://iallpowers.com/pages/affiliate-program', 'official_site', 'affiliate', 'ALLPOWERS'' own affiliate page fetched in full: ''Commission up to 10%'', ''A 5%+ base rate with performance tiers up to 10%'', 30-day cookie window, $500+ average order value, applications typically reviewed within 48 hours, and joining via ''CJ, Awin, AvantLink or GoAffPro''. The page names its audience as creators and influencers (outdoor, technology, RV, preparedness, home-energy), publishers and review sites, and publishes the affiliate team contact marketing@allpowers.com. No earnings-cap statement and no creator count are published, so cap and saturation stay unknown.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://ui.awin.com/merchant-profile/40342', 'network', 'affiliate', 'ALLPOWERS'' Awin merchant profile (US & CA) lists commission of 5%-8% on all sales, a 30-day cookie, an average $500 order value and monthly performance incentives, corroborating the base rate on the brand''s own page.', 'publicly_reported', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 24, 15, 11, 12, 8, 4, '{"niche_fit": "Power stations and solar kits anchor outdoor, RV, prepper and home-backup creator content; the brand lists exactly those niches.", "ugc_evidence": "A creator-first program page: field tests, home-backup guides and outdoor stories are the named content formats, with banners and approved offers supplied.", "compensation": "5% base with tiers to 10% on a $500+ average order and a 30-day cookie; exact rate varies by network and no cap statement is published.", "contact_access": "Published affiliate-team email (marketing@allpowers.com) plus four network application routes \u2014 several ways in.", "opportunity_availability": "Live program with a stated ~48-hour application review across four networks.", "credibility": "Consistent terms across the brand''s own page and its Awin profile; an established portable-power brand."}'::jsonb);
