  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://oupes.com/pages/affiliate-program', 'official_site', 'affiliate', 'OUPES'' own affiliate page fetched in full: ''Join OUPES and Earn 5% for every referral'', ''At least 5% commission'', a stated $1,000 average order value, ''Cookies Last 60 days'', exclusive discount codes and a dedicated marketing manager, with sign-up via its affiliate program partners. No earnings-cap statement and no creator count are published, so cap and saturation stay unknown.', 'verified', now());
