  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 22, 11, 11, 8, 8, 3, '{"niche_fit": "Home-backup and off-grid power stations fit tech, prepper and RV creator content well.", "ugc_evidence": "A live partner page with discount codes and a named dedicated marketing manager, though less creator-specific than rivals'' pages.", "compensation": "Flat published 5% on a stated $1,000 average order with a generous 60-day cookie; no cap statement published.", "contact_access": "Network application routes from the brand''s page; no published affiliate email.", "opportunity_availability": "Program live on Awin with the brand actively promoting partner sign-up.", "credibility": "Terms agree across the brand page and Awin; a smaller brand than the category leaders, so a point is held back."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('TORRAS', 'https://torraslife.com', 'Consumer tech accessories brand founded in 2012, best known for Ostand phone cases, screen protectors and cooling chargers, claiming 100M+ customers across 148 regions. Its own affiliate page routes applicants to Impact, advertises commission rates going up to 15%, a 30-day cookie and a claimed 3%+ average conversion rate.', 'China', 'published') returning id into bid;
