  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://torraslife.com/pages/affiliate', 'official_site', 'affiliate', 'TORRAS'' own affiliate page fetched in full: ''our commission rates go up to 15%'', ''30-Day cookies'', ''averages 3%+ CVR'', and instructions to apply through its Impact link and share ''an affiliate link provided by Impact''. The page publishes no base commission rate, no earnings-cap statement and no creator count, so the recorded rate is null and cap and saturation stay unknown.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.wowtrk.com/offer/3826593', 'directory', 'affiliate', 'A network offer listing for TORRAS (ClickDealer/WOWTRK) shows an 8% of order sale amount base with bonus tiers to 8.8% and 9.6% at monthly revenue thresholds and a 30-day cookie — a different route from the Impact program on the brand''s page, which is why no single rate is recorded. The listing describes TORRAS as founded in 2012 with 100M+ customers in 148 regions.', 'publicly_reported', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 25, 14, 9, 8, 8, 4, '{"niche_fit": "Phone cases and charging accessories are staple tech-creator review and roundup content with constant new-product cycles.", "ugc_evidence": "A dedicated affiliate page on the brand''s own store routing creators into Impact, with conversion claims aimed at promoters.", "compensation": "Only a ceiling is published (''up to 15%'') on the official page and a separate network lists 8% base, so no rate is recorded; no cap statement published.", "contact_access": "Impact application linked from the brand''s page; no published affiliate email.", "opportunity_availability": "Program live on Impact, a mainstream creator-friendly network.", "credibility": "Large claimed customer base and a long trading history since 2012; rate opacity keeps compensation scored conservatively."}'::jsonb);
