  insert into public.brands (name, website, description, country, status) values ('Dupray', 'https://dupray.com', 'Canadian premium home-appliance brand making steam cleaners, garment steamers, air purifiers and spot cleaners for chemical-free home cleaning. It runs its own creator affiliate program on Refersion whose published terms are written around social creators (Instagram, TikTok, YouTube, blogs), and a parallel ShareASale program reported at 10%.', 'Canada', 'published') returning id into bid;
