  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Dupray Affiliate Program (own program on Refersion) — creator program for steam-cleaning content; ShareASale route also reported at 10%', 'https://dupray.refersion.com', 'https://dupray.refersion.com', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://dupray.refersion.com', 'official_site', 'affiliate', 'Dupray''s own Refersion affiliate agreement fetched in full: the program is defined around creators displaying products on Instagram, Facebook, TikTok, YouTube or a blog in exchange for commission; commission fees are paid within 60 days once an affiliate''s total exceeds $150 USD via PayPal or bank deposit. The agreement states the commission amount ''shall be determined by Dupray and the Affiliate'', so no rate is published in the brand''s own terms and the recorded rate is null. No earnings-cap statement and no creator count appear, so cap and saturation stay unknown.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://dupray.com/en-gb/pages/faq', 'official_site', 'affiliate', 'Dupray''s official FAQ confirms the program publicly — ''Do you have an affiliate or influencer program? Yes! If you''re a content creator... we''d love to have you join our Dupray Affiliate Program'' — and describes Dupray as ''a Canadian brand'' of high-end household appliances including steam cleaners, clothes steamers, air purifiers and spot cleaners.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://linkmydeals.com/affiliate-programs/info/dupray.com/', 'network', 'affiliate', 'Network listings for dupray.com report a parallel ShareASale program at a 10% sale commission (ShareASale CID 125866), with a high reported approval rate. This network rate is documented here rather than recorded, because the brand''s own program terms do not publish a rate.', 'publicly_reported', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 21, 15, 9, 8, 7, 4, '{"niche_fit": "Steam cleaning and chemical-free home care are durable home-creator niches with strong before/after video formats.", "ugc_evidence": "The brand''s own program terms are written specifically for social creators on TikTok, Instagram and YouTube, and its FAQ publicly recruits content creators.", "compensation": "No rate is published in the brand''s own terms (set per affiliate) and payouts need a $150 balance; a parallel ShareASale listing reports 10%, so compensation is scored cautiously.", "contact_access": "Application through the brand''s own program page; no published affiliate email.", "opportunity_availability": "Program is live but acceptance is expressly at Dupray''s discretion after review.", "credibility": "Established premium Canadian brand selling into the US and Canada with full published program terms."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Geneverse', 'https://geneverse.com', 'Home backup-power brand (HomePower solar generators and power stations) positioned as emergency power for homes and communities. Its CJ Affiliate program description publishes 6% sale commissions, a 30-day cookie, exclusive payouts and bonus programs, with in-house affiliate management.', 'United States', 'published') returning id into bid;
  insert into public.brand_categories (brand_id, category_id, is_primary) values (bid, (select id from public.categories where slug = 'technology'), true);
  insert into public.brand_contacts (brand_id, contact_type, email, contact_url, source_url, verification_status, last_verified_at) values (bid, 'creator_application', null, 'https://www.affiliate-toolkit.com/program/geneverse-com/', 'https://www.affiliate-toolkit.com/program/geneverse-com/', 'needs_review', null);
  insert into public.affiliate_programs (brand_id, network, commission_rate, commission_notes, application_url, status, last_checked_at) values (bid, 'CJ', 6, 'Commission cap: not stated in any published source found — needs review. Creator saturation: unknown (see evidence). Rate as reported by https://www.affiliate-toolkit.com/program/geneverse-com/.', 'https://www.affiliate-toolkit.com/program/geneverse-com/', 'needs_review', now());
  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Geneverse Affiliate Program on CJ — 6% sale commissions, 30-day cookie, bonus payout program', 'https://www.affiliate-toolkit.com/program/geneverse-com/', 'https://www.affiliate-toolkit.com/program/geneverse-com/', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.affiliate-toolkit.com/program/geneverse-com/', 'network', 'affiliate', 'Geneverse''s CJ program description, reproduced in full: ''what you get… 6% sale commissions, exclusive payouts, bonus payout program and vanities for custom placements, 30-day cookie, in-house affiliate management'', describing Geneverse as ''the most reliable source of emergency backup power for your home and community'' around its HomePower One station and SolarPower One panel. The recorded route is CJ at the published 6%. No earnings-cap statement and no creator count are published, so cap and saturation stay unknown.', 'publicly_reported', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://linkclicky.com/affiliate-program/geneverse/', 'directory', 'affiliate', 'A program directory lists Geneverse on CJ Affiliate at 3%-6% per sale, consistent with the 6% headline in the CJ program description; the range is why the recorded rate uses the program''s own published 6% figure with this range noted.', 'publicly_reported', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 22, 11, 11, 7, 8, 3, '{"niche_fit": "Whole-home emergency backup power fits prepper, homestead and smart-home creator content.", "ugc_evidence": "A CJ program with vanities for custom placements and in-house management suggests active publisher recruitment, though creator-specific evidence is thinner than rivals''.", "compensation": "Published 6% sale commissions on high-value home power stations with bonus payouts; directory reporting of a 3%-6% range is noted and no cap statement is published.", "contact_access": "CJ application route only; the program''s agency contact was not cleanly published, so no email is recorded.", "opportunity_availability": "Live CJ program with standard network application.", "credibility": "A recognised home-backup brand; evidence rests on network-published program copy rather than the brand''s own site, so a point is held back."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Alen', 'https://www.alen.com', 'US air-purifier brand (BreatheSmart line) selling HEPA purifiers and smart bundles direct to consumers. It runs an affiliate program paying commission on qualifying sales of purifiers and bundles, listed on FlexOffers at 4% with a 30-day cookie, and publishes an affiliate contact email on its program page.', 'United States', 'published') returning id into bid;
  insert into public.brand_categories (brand_id, category_id, is_primary) values (bid, (select id from public.categories where slug = 'home'), true);
  insert into public.brand_contacts (brand_id, contact_type, email, contact_url, source_url, verification_status, last_verified_at) values (bid, 'partnerships', 'affiliates@alencorp.com', 'https://alencorp-development-store.myshopify.com/pages/alen-affiliate-program', 'https://alencorp-development-store.myshopify.com/pages/alen-affiliate-program', 'needs_review', null);
  insert into public.affiliate_programs (brand_id, network, commission_rate, commission_notes, application_url, status, last_checked_at) values (bid, 'FlexOffers', 4, 'Commission cap: not stated in any published source found — needs review. Creator saturation: unknown (see evidence). Rate as reported by https://www.flexoffers.com/affiliate-programs/alen-corporation-affiliate-program/.', 'https://alencorp-development-store.myshopify.com/pages/alen-affiliate-program', 'needs_review', now());
  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Alen Affiliate Program — 4% commission on air purifiers, 30-day cookie (program page flagged for review)', 'https://alencorp-development-store.myshopify.com/pages/alen-affiliate-program', 'https://www.flexoffers.com/affiliate-programs/alen-corporation-affiliate-program/', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://alencorp-development-store.myshopify.com/pages/alen-affiliate-program', 'official_site', 'affiliate', 'Alen''s own affiliate program page — found on a development-store subdomain of its Shopify store, which is why this evidence is flagged needs_review: ''Alen''s affiliate program provides you with a way to link your site to our best-in-class air purifiers, all while earning a commission on all qualifying sales... Apply now to start earning commissions on Air Purifiers, Smart Bundles and more'', with an approval process and the published contact affiliates@alencorp.com. The page publishes no rate, cap statement or creator count.', 'needs_review', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.flexoffers.com/affiliate-programs/alen-corporation-affiliate-program/', 'network', 'affiliate', 'FlexOffers'' listing for the Alen Air Purifiers affiliate program: affiliates ''can earn a 4% commission on online sales, and 1.6% for select items'', with a 30-day cookie duration. The recorded rate is the headline 4%. No earnings-cap statement and no creator count are published anywhere fetched, so cap and saturation stay unknown.', 'publicly_reported', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 21, 10, 7, 10, 7, 4, '{"niche_fit": "Air quality, allergies and sleep are steady home and wellness creator topics, and purifiers demo well on video.", "ugc_evidence": "A dedicated affiliate program page with application and resources, though it speaks to site publishers more than social creators.", "compensation": "4% headline rate (1.6% on select items) is the lowest in this group, partly offset by premium unit prices; no cap statement published.", "contact_access": "A published affiliate email (affiliates@alencorp.com) plus an application page \u2014 though the page sits on a development subdomain and is flagged for review.", "opportunity_availability": "Program listed live on FlexOffers with an application and short approval process per the brand page.", "credibility": "An established US purifier brand; the dev-subdomain program page is the one blemish and is flagged needs_review."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Meowant', 'https://meowant.com', 'US smart cat-care brand founded in 2013, best known for self-cleaning litter boxes (MW-SC01/SC02/SC09/SC10) plus pet air purifiers, water fountains, feeders and a GPS dog fence. It runs its own affiliate program page and is listed across many networks including Awin and FlexOffers.', 'United States', 'published') returning id into bid;
  insert into public.brand_categories (brand_id, category_id, is_primary) values (bid, (select id from public.categories where slug = 'pets'), true);
  insert into public.brand_contacts (brand_id, contact_type, email, contact_url, source_url, verification_status, last_verified_at) values (bid, 'creator_application', null, 'https://meowant.com/pages/affiliate', 'https://meowant.com/pages/affiliate', 'verified', now());
  insert into public.affiliate_programs (brand_id, network, commission_rate, commission_notes, application_url, status, last_checked_at) values (bid, 'Awin', null, 'Commission cap: not stated in any published source found — needs review. Creator saturation: unknown (see evidence). Rate as reported by https://meowant.com/pages/affiliate.', 'https://meowant.com/pages/affiliate', 'needs_review', now());
  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Meowant Affiliate Program — own program page plus Awin and other network routes; rates vary by network (7.5%-11.25% reported)', 'https://meowant.com/pages/affiliate', 'https://meowant.com/pages/affiliate', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://meowant.com/pages/affiliate', 'official_site', 'affiliate', 'Meowant''s own affiliate program page fetched (''Join Our Pet Product Affiliate Program & Earn Commissions''), presenting its self-cleaning litter boxes, GPS dog fence, water fountains, feeders and pet air purifiers as the promotable range. The fetched page publishes no commission rate, no earnings-cap statement and no creator count, so the recorded rate is null and cap and saturation stay unknown. The page and network listings describe Meowant as a US pet brand founded in 2013.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.affiliate-program.io/en/brands/meowant', 'directory', 'affiliate', 'A network roundup lists 11-12 Meowant programs across Awin, FlexOffers, SaleGains, Skimlinks, Cuelinks, Sovrn and others, with conflicting reference rates — FlexOffers at 10.4% of sales, Cuelinks at 9.0% base (11.25% on the SC01), SaleGains references from 7.5% — which is why no single rate is recorded. The recorded route is Awin, one of the listed networks carrying the program.', 'publicly_reported', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 24, 12, 9, 7, 8, 3, '{"niche_fit": "Self-cleaning litter boxes are one of the most-reviewed products in cat-creator content, and the range extends to fountains, feeders and purifiers.", "ugc_evidence": "An own affiliate page plus listings across a dozen networks show active, broad affiliate recruitment.", "compensation": "Reported rates cluster around 7.5%-11.25% but conflict by network and product, and the brand''s own page publishes none, so no rate is recorded.", "contact_access": "Own program page and network applications; no published affiliate email.", "opportunity_availability": "Many simultaneous network routes make joining easy; terms must be confirmed per network.", "credibility": "Trading since 2013 with a broad retail footprint; thinner brand-published program detail than rivals keeps credibility mid-band."}'::jsonb);
